#include <stdio.h>
#include <string.h>

#define MOD 1000000007

int dp[10001][101][2];
char K[10001];
int len, D;

int solve(int pos, int sum_mod, int tight) {
    if (pos == len) {
        return (sum_mod == 0) ? 1 : 0;
    }
    if (dp[pos][sum_mod][tight] != -1) {
        return dp[pos][sum_mod][tight];
    }

    int limit = tight ? (K[pos] - '0') : 9;
    int res = 0;
    for (int d = 0; d <= limit; d++) {
        int next_tight = tight && (d == limit);
        res = (res + solve(pos + 1, (sum_mod + d) % D, next_tight)) % MOD;
    }

    dp[pos][sum_mod][tight] = res;
    return res;
}

