#include <string.h>

#define MOD 1000000007

int digits[20];
int len;
int D;
long long memo[20][100][2][2];
int visited[20][100][2][2];

long long solve(int pos, int rem, int tight, int started) {
    if (pos == len) {
        if (!started) return 0;
        return rem == 0 ? 1 : 0;
    }
    if (visited[pos][rem][tight][started]) return memo[pos][rem][tight][started];
    visited[pos][rem][tight][started] = 1;

    int limit = tight ? digits[pos] : 9;
    long long res = 0;
    for (int d = 0; d <= limit; d++) {
        int new_tight = tight && (d == limit);
        int new_started = started || (d != 0);
        int new_rem = started || (d != 0) ? (rem + d) % D : 0;
        res = (res + solve(pos + 1, new_rem, new_tight, new_started)) % MOD;
    }
    memo[pos][rem][tight][started] = res;
    return res;
}

