#include <stdio.h>
#include <string.h>

#define MOD 1000000007LL

int main(void) {
    char K[10005];
    int D;

    if (scanf("%s %d", K, &D) != 2) return 0;

    int n = (int)strlen(K);

    static long long dp[10005][105];
    static long long ndp[10005][105];

    dp[0][0] = 1;

    for (int i = 0; i < n; i++) {
        for (int r = 0; r < D; r++) ndp[i + 1][r] = 0;

        int digit = K[i] - '0';
        for (int r = 0; r < D; r++) {
            long long cur = dp[i][r];
            if (!cur) continue;
            for (int d = 0; d <= digit; d++) {
                int nr = (r + d) % D;
                ndp[i + 1][nr] = (ndp[i + 1][nr] + cur) % MOD;
            }
        }

        for (int len = 1; len <= i + 1; len++) {
            for (int r = 0; r < D; r++) {
                dp[len][r] = ndp[len][r];
            }
        }
    }

    // The above is not enough for digit DP with tightness.
    // Use proper DP: dp[pos][mod][tight]
    static long long f[10005][105][2];
    memset(f, 0, sizeof(f));
    f[0][0][1] = 1;

    for (int i = 0; i < n; i++) {
        int lim = K[i] - '0';
        for (int r = 0; r < D; r++) {
            f[i + 1][r][0] = 0;
            f[i + 1][r][1] = 0;
        }
        for (int r = 0; r < D; r++) {
            for (int tight = 0; tight <= 1; tight++) {
                long long cur = f[i][r][tight];
                if (!cur) continue;
                int up = tight ? lim : 9;
                for (int d = 0; d <= up; d++) {
                    int ntight = (tight && d == up) ? 1 : 0;
                    int nr = (r + d) % D;
                    f[i + 1][nr][ntight] += cur;
                    if (f[i + 1][nr][ntight] >= MOD) f[i + 1][nr][ntight] %= MOD;
                }
            }
        }
    }

    long long ans = (f[n][0][0] + f[n][0][1] - 1) % MOD; // exclude 0
    if (ans < 0) ans += MOD;

    printf("%lld\n", ans);
    return 0;
}

