const int MOD = 1e9 + 7;

int main() {
    long long K;
    int D;
    cin >> K >> D;

    string s = to_string(K);
    int n = s.size();

    // dp[tight][remainder]
    // We'll do iterative digit DP
    // dp[r] = count of numbers with digit sum ≡ r (mod D), with tight constraint

    vector<long long> dp_tight(D, 0), dp_free(D, 0);
    dp_tight[0] = 1; // empty prefix, tight

    for (int i = 0; i < n; i++) {
        vector<long long> new_tight(D, 0), new_free(D, 0);
        int lim = s[i] - '0';

        // From tight states
        for (int r = 0; r < D; r++) {
            if (dp_tight[r] == 0) continue;
            // digits 0 to lim-1: become free
            for (int d = 0; d < lim; d++) {
                new_free[(r + d) % D] = (new_free[(r + d) % D] + dp_tight[r]) % MOD;
            }
            // digit lim: stay tight
            new_tight[(r + lim) % D] = (new_tight[(r + lim) % D] + dp_tight[r]) % MOD;
        }

        // From free states
        for (int r = 0; r < D; r++) {
            if (dp_free[r] == 0) continue;
            for (int d = 0; d <= 9; d++) {
                new_free[(r + d) % D] = (new_free[(r + d) % D] + dp_free[r]) % MOD;
            }
        }

        dp_tight = new_tight;
        dp_free = new_free;
    }

    // Count numbers from 0 to K with digit sum divisible by D
    long long ans = (dp_tight[0] + dp_free[0]) % MOD;
    // Subtract 1 for the number 0
    ans = (ans - 1 + MOD) % MOD;

    cout << ans << endl;

    return 0;
}

