static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string K;
    int D;
    cin >> K >> D;

    vector<long long> dp_tight(D, 0), dp_loose(D, 0);
    dp_tight[0] = 1; // no digits yet

    for (char c : K) {
        int digit = c - '0';
        vector<long long> ndp_tight(D, 0), ndp_loose(D, 0);

        for (int sum = 0; sum < D; ++sum) {
            // Transition from tight state
            if (dp_tight[sum]) {
                for (int d = 0; d <= digit; ++d) {
                    int nsum = (sum + d) % D;
                    if (d == digit) {
                        ndp_tight[nsum] = (ndp_tight[nsum] + dp_tight[sum]) % MOD;
                    } else {
                        ndp_loose[nsum] = (ndp_loose[nsum] + dp_tight[sum]) % MOD;
                    }
                }
            }

            // Transition from loose state
            if (dp_loose[sum]) {
                for (int d = 0; d <= 9; ++d) {
                    int nsum = (sum + d) % D;
                    ndp_loose[nsum] = (ndp_loose[nsum] + dp_loose[sum]) % MOD;
                }
            }
        }

        dp_tight.swap(ndp_tight);
        dp_loose.swap(ndp_loose);
    }

    long long ans = (dp_tight[0] + dp_loose[0] - 1 + MOD) % MOD; // exclude 0
    cout << ans << '\n';
    return 0;
}

