        for (int i = 0; i < n; i++) {
            int digit = K.charAt(i) - '0';
            int[][] next = new int[D][2];

            for (int mod = 0; mod < D; mod++) {
                for (int tight = 0; tight < 2; tight++) {
                    int cur = dp[mod][tight];
                    if (cur == 0) continue;
                    int limit = tight == 1 ? digit : 9;
                    for (int d = 0; d <= limit; d++) {
                        int nextMod = (mod + d) % D;
                        int nextTight = (tight == 1 && d == limit) ? 1 : 0;
                        next[nextMod][nextTight] = (next[nextMod][nextTight] + cur) % MOD;
                    }
                }
            }
            dp = next;
        }

        int ans = (dp[0][0] + dp[0][1] - 1) % MOD;
        if (ans < 0) ans += MOD;
        System.out.println(ans);
