public class Main {
    static long MOD = 1_000_000_007;
    static int D;
    static char[] digits;
    static long[][][] memo;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        String K = st.nextToken();
        D = Integer.parseInt(st.nextToken());

        digits = K.toCharArray();
        int n = digits.length;
        // memo[pos][sum_mod_D][tight]
        memo = new long[n + 1][D][2];
        for (long[][] a : memo)
            for (long[] b : a)
                Arrays.fill(b, -1);

        long result = dp(0, 0, 1);
        // subtract 1 if 0 is counted (sum of digits of 0 is 0, which is divisible by D)
        // Actually we need 1 to K, so subtract the case for number 0
        // dp counts from 0 to K, so if 0 is included (digit sum 0 is multiple of D), subtract 1
        result = (result - 1 + MOD) % MOD;

        System.out.println(result);
    }

    // pos: current position in digits
    // sumMod: current sum of digits mod D
    // tight: whether we're still bounded by K
    static long dp(int pos, int sumMod, int tight) {
        if (pos == digits.length) {
            return sumMod == 0 ? 1 : 0;
        }

        if (memo[pos][sumMod][tight] != -1) {
            return memo[pos][sumMod][tight];
        }

        int limit = tight == 1 ? (digits[pos] - '0') : 9;
        long res = 0;

        for (int d = 0; d <= limit; d++) {
            int newTight = (tight == 1 && d == limit) ? 1 : 0;
            int newSum = (sumMod + d) % D;
            res = (res + dp(pos + 1, newSum, newTight)) % MOD;
        }

        memo[pos][sumMod][tight] = res;
        return res;
    }
}

