            int limitDigit = K.charAt(i) - '0';
            long[][] next = new long[D][2];

            for (int rem = 0; rem < D; rem++) {
                for (int tight = 0; tight <= 1; tight++) {
                    long cur = dp[rem][tight];
                    if (cur == 0) continue;

                    int maxDigit = (tight == 1) ? limitDigit : 9;
                    for (int dig = 0; dig <= maxDigit; dig++) {
                        int ntight = (tight == 1 && dig == maxDigit) ? 1 : 0;
                        int nrem = (rem + dig) % D;
                        next[nrem][ntight] += cur;
                        if (next[nrem][ntight] >= MOD) next[nrem][ntight] -= MOD;
                    }
                }
            }
            dp = next;
        }

        long ans = (dp[0][0] + dp[0][1] - 1 + MOD) % MOD; // exclude 0
